t.script:
                function updateSkills() {
                    var path = document.getElementById('path_select').value;
                    var section = document.getElementById('skills_section');
                    var options = document.getElementById('skills_options');
                    options.innerHTML = '';

                    var skillsMap = {
                        'office': ['السكرتاريه', 'ادخال البيانات المكتبية'],
                        'technical': ['التسويق الالكتروني', 'التصميم الجرافيك', 'تصميم المؤثرات', 'التصوير الفوتوغرافي'],
                        'handicraft': ['الخط العربي', 'صناعة العطور', 'صيانة الاجهزه', 'الصيانه المنزليه']
                    };

                    if (path && skillsMap[path]) {
                        section.classList.remove('d-none');
                        skillsMap[path].forEach(function(skill) {
                            var col = document.createElement('div');
                            col.className = 'col-md-6 mb-2';
                            col.innerHTML = '
' +
                                '' +
                                '' + skill + '' +
                            '';
                            options.appendChild(col);
                        });
                    } else {
                        section.classList.add('d-none');
                    }
                }
